 "remembered_experiences": [
  {
   "morning_observation": "Tuesday, February 2, 2016. The local radio plays three bright notes and announces a groundhog forecast in the town square. A delivery van backfires twice.",
   "episodes_in_order": [
    "6:00 am in inn: Rita spends the period at the inn. Phil says: Copy. Chart's in the bag by the coat. You want me to hold position here till you cue, or are you running the ident over me again? Phil spends the period at the inn. Rita invites Phil on the crew radio to contribute to the evening slot.",
    "9:30 am in inn: Rita spends the period at the inn. Phil says: Copy. Chart'll be done by six. Phil spends the period at the inn. Phil radios Rita and accepted the evening assignment.",
    "1:00 pm in inn: Rita spends the period at the inn. Phil says: One o'clock coach. I'll be on the phone return at seven sharp. And Rita—queue me before the ident, not under it. Last thing I need is my chart dissolving under the station sting. Phil leaves the inn. Rita invites Larry on the crew radio to contribute to the evening slot."
   ]
  },
  {
   "most_recent_own_plan": "Head to the square next period to locate the town band and set up a live pickup for the seven o'clock slot."
  }
 ],
